-- The website in grandpokerarena.com's way, page by page (owner, 26 Oct 2026; decision 0166): the front
-- page in its order of bands, and its pages (about, membership, promotions, tournaments, the journal and
-- its articles, terms), in RIVR's own words and media. What only the owner can say stays a placeholder,
-- said as one: the points rates (question #395), the Black card's terms and the terms of use. Until the
-- console edits the website (C-020), the seed owns these pages: every run, staging's deploy included,
-- puts their blocks back as they are here. Runs after 40_site.sql and 41_site_pages.sql.

insert into public.site_page (id, venue_id, slug, title, description, nav_position, is_published) values
  ('00000000-0000-4000-8000-0000000005d1', '00000000-0000-4000-8000-000000000001', 'about', 'About',
   'RIVR, a members'' poker club in Gurugram: the room, the standard and the rules.', 1, true),
  ('00000000-0000-4000-8000-0000000005d2', '00000000-0000-4000-8000-000000000001', 'membership', 'Membership',
   'Join RIVR: tiers earned at the table, points for every hour, and how to sign up.', 2, true),
  ('00000000-0000-4000-8000-0000000005d3', '00000000-0000-4000-8000-000000000001', 'promotions', 'Promotions',
   'What RIVR runs on the house, live from the floor.', 3, true),
  ('00000000-0000-4000-8000-0000000005d4', '00000000-0000-4000-8000-000000000001', 'tournaments', 'Tournaments',
   'RIVR''s tournament calendar, from RIVR Sunday to the weekly games.', 4, true),
  ('00000000-0000-4000-8000-0000000005d5', '00000000-0000-4000-8000-000000000001', 'journal', 'Journal',
   'Strategy, rules and etiquette, written by people who play.', 6, true),
  ('00000000-0000-4000-8000-0000000005d6', '00000000-0000-4000-8000-000000000001', 'journal-holdem-basics', 'Texas Hold''em for beginners',
   'The rules of No-Limit Hold''em, from the blinds to the showdown.', null, true),
  ('00000000-0000-4000-8000-0000000005d7', '00000000-0000-4000-8000-000000000001', 'journal-plo-basics', 'Pot-Limit Omaha: what changes',
   'Four cards, two of them used, and a bet no bigger than the pot.', null, true),
  ('00000000-0000-4000-8000-0000000005d8', '00000000-0000-4000-8000-000000000001', 'journal-live-etiquette', 'Live poker etiquette',
   'How a live table runs, and how to be the player others want beside them.', null, true),
  ('00000000-0000-4000-8000-0000000005d9', '00000000-0000-4000-8000-000000000001', 'journal-bankroll', 'Bankroll basics',
   'Playing within your means, so a bad night stays a bad night.', null, true),
  ('00000000-0000-4000-8000-0000000005da', '00000000-0000-4000-8000-000000000001', 'terms', 'Terms of use',
   'The terms of RIVR''s website and app.', null, true)
on conflict (id) do update set title = excluded.title, description = excluded.description, nav_position = excluded.nav_position,
  is_published = excluded.is_published;

-- The header's pages, in GPA's order: the club, membership, what's on, the journal and where to find it.
-- The house rules, questions, responsible play, privacy and terms move to the footer.
update public.site_page set nav_position = 5 where id = '00000000-0000-4000-8000-0000000005a2';
update public.site_page set nav_position = 7, title = 'Visit' where id = '00000000-0000-4000-8000-0000000005b3';
update public.site_page set nav_position = null
where id in ('00000000-0000-4000-8000-0000000005b1', '00000000-0000-4000-8000-0000000005b2', '00000000-0000-4000-8000-0000000005b4',
             '00000000-0000-4000-8000-0000000005b5');

-- The visit page also says how to write to the club.
update public.site_block set content = content || '{"email": "info@rivrpoker.com"}'::jsonb
where page_id = '00000000-0000-4000-8000-0000000005b3' and kind = 'map';

delete from public.site_block where page_id in (
  '00000000-0000-4000-8000-0000000005a1', '00000000-0000-4000-8000-0000000005d1', '00000000-0000-4000-8000-0000000005d2',
  '00000000-0000-4000-8000-0000000005d3', '00000000-0000-4000-8000-0000000005d4', '00000000-0000-4000-8000-0000000005d5',
  '00000000-0000-4000-8000-0000000005d6', '00000000-0000-4000-8000-0000000005d7', '00000000-0000-4000-8000-0000000005d8',
  '00000000-0000-4000-8000-0000000005d9', '00000000-0000-4000-8000-0000000005da');

-- The front page, band by band in GPA's order.
insert into public.site_block (venue_id, page_id, position, kind, content)
select '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000005a1', b.position, b.kind, b.content::jsonb
from (values
  (1, 'hero', $${"eyebrow": "RIVR Poker Club · Gurugram", "heading": "Bring your poker face.", "text": "A members' poker club at Glaza, M3M 65th Avenue. Dealers at every table, a cage that pays out the same night, and a floor you follow from your phone. Opens Sunday 15 November.", "action": {"label": "Join RIVR", "to": "sign-up"}, "video": {"src": "/media/hero-room.mp4", "poster": "/media/hero-room.webp"}, "note": "Concept visualisation"}$$),
  (2, 'marquee', $${"phrases": ["Play", "Connect", "Belong", "Members only", "Six tables", "Opens 15 November", "Hold your nerve", "Gurugram"]}$$),
  (3, 'story', $${"eyebrow": "Our story", "heading": "Good hands. Better company.", "paragraphs": ["RIVR opens on Sunday 15 November with one idea: Gurugram's serious players deserve a room built for them.", "Not a casino, and not a card table in the corner of a bar. A members' club on the upper floor of Glaza, where every player is verified, every dealer is trained, and every decision at the table is yours."], "figures": [{"value": "6", "label": "Tables, from 50/100 to the Private Room"}, {"value": "18+", "label": "Verified members at every seat"}, {"value": "₹50", "label": "The smallest chip"}, {"value": "Same night", "label": "Cash-outs at the cage"}], "action": {"label": "Join RIVR", "to": "sign-up"}, "image": "/media/room.webp", "alt": "The main room under its chandeliers"}$$),
  (4, 'cards', $${"eyebrow": "What we stand for", "heading": "Play. Connect. Belong.", "intro": "Three words, and three promises to every member who walks in.", "cards": [{"label": "01 · Play", "title": "The game, done properly.", "text": "Poker is a game of skill, so we run it like one.", "points": ["Trained dealers on a rotation", "No-limit hold'em and pot-limit Omaha", "Every hand logged at the table", "The floor's decision is final"]}, {"label": "02 · Connect", "title": "A room full of regulars.", "text": "The best part of a good game is who sits across from you.", "points": ["Tournaments every week", "RIVR Sunday, our flagship", "The RIVR League, a champion each season"]}, {"label": "03 · Belong", "title": "Members, not customers.", "text": "Everyone here is verified, known and looked after.", "points": ["Tiers that rise with your hours", "First call for the Founders' Circle", "A host who knows your game"], "link": {"label": "See membership", "page": "membership"}}]}$$),
  (5, 'statement', $${"eyebrow": "The RIVR difference", "lines": ["Not luck.", "A game of skill."], "text": "Cash games and tournaments dealt by casino-trained dealers, with every hand logged at the table."}$$),
  (6, 'gallery', $${"eyebrow": "Inside RIVR", "heading": "Built for the long session.", "intro": "Everything around the table is looked after, so the game is all you think about.", "items": [{"image": "/media/members.webp", "alt": "A host greets members at the club's door", "title": "A private members' club", "text": "Members and their guests only."}, {"image": "/media/dealers.webp", "alt": "A dealer in a waistcoat deals at a table", "title": "Casino-trained dealers", "text": "Fast, accurate, fair."}, {"image": "/media/cashier.webp", "alt": "A cashier counts chips at the cage", "title": "Instant, secure cashier", "text": "Clean counts, paid out the same night."}, {"image": "/media/private-room.webp", "alt": "A private table under a single lamp", "title": "Private high-stakes room", "text": "Discreet, for bigger action."}, {"image": "/media/chefs-menu.webp", "alt": "A plate served beside a table in play", "title": "Complimentary chef's menu", "text": "Served at your seat."}, {"image": "/media/pick-up.webp", "alt": "A chauffeur holds a car door outside the club at night", "title": "Pick-up and drop", "text": "Chauffeured rides for regulars."}, {"image": "/media/built-for-her.webp", "alt": "Friends laughing together at a table in the club", "title": "Built for her, too", "text": "A room where everyone is at home at the table."}, {"image": "/media/room.webp", "alt": "The main room under its chandeliers", "title": "The main room", "text": "A dealer at every table, every night."}], "note": "Concept visualisation"}$$),
  (7, 'cards', $${"eyebrow": "The room", "heading": "Everything around the felt.", "intro": "The upper floor of Glaza, on M3M 65th Avenue. Built so the only thing on your mind is the next decision.", "cards": [{"label": "05", "title": "The main room", "text": "Five tables of no-limit hold'em, from 50/100 to 100/200, each with its dealer and its tablet."}, {"label": "01", "title": "The Private Room", "text": "One table at 100/200 with a compulsory ₹500 straddle, for the game you want behind a door."}, {"title": "Trained dealers", "text": "On a rotation, with every pot counted and every hand logged on the table's tablet."}, {"title": "The cage", "text": "Buy in by UPI or in cash. Cash out the same night."}, {"title": "The chef's menu", "text": "Complimentary, and served at your seat."}, {"title": "Safe and secure", "text": "CCTV across the club, staff on the floor, and verified members only."}]}$$),
  (8, 'games', $${"heading": "Pick your table."}$$),
  (9, 'cards', $${"eyebrow": "Hospitality", "heading": "Looked after, every hour.", "intro": "You come for the game. Everything else is our job.", "cards": [{"title": "At your seat", "text": "The chef's menu, served without leaving the table."}, {"title": "Your host", "text": "A host who knows your game, holds your seat and takes care of the details."}, {"title": "Pick-up and drop", "text": "Chauffeured rides for regulars, and a cab home from your fourth visit in a month."}, {"title": "The RIVR app", "text": "See tonight's tables, join the waitlist from home and get called to your seat."}], "quote": "The only thing on your mind should be the next decision."}$$),
  (10, 'cards', $${"eyebrow": "The standard", "heading": "Played straight. Every hand.", "intro": "A members' club is only as good as the rules behind it. Ours are simple, strict and the same for everyone.", "cards": [{"title": "Members only", "text": "18 and over, with your identity checked by DigiLocker and a selfie before you take a seat."}, {"title": "Watched, always", "text": "CCTV across the club, and a floor manager on every shift."}, {"title": "Fair play", "text": "Collusion, chip dumping and soft play are banned. One player to a hand. The floor's decision is final.", "link": {"label": "Read the house rules", "page": "house-rules"}}, {"title": "Clean money", "text": "Your own money only. Chips never leave the club, and the cage pays out to you and you alone."}, {"title": "Tax compliant", "text": "TDS is deducted on winnings as the law requires, and the cage asks for your PAN."}, {"title": "Play responsibly", "text": "Set a limit or take a break whenever you like. The door, the waitlist and the cage keep it.", "link": {"label": "Responsible play", "page": "responsible-play"}}]}$$),
  (11, 'timeline', $${"eyebrow": "On the record", "heading": "A game of skill, on the record.", "intro": "India's Supreme Court has long drawn the line between games of skill and games of chance.", "items": [{"when": "1968", "title": "State of Andhra Pradesh v. K. Satyanarayana", "text": "The Supreme Court holds that rummy, played for stakes, is a game of skill."}, {"when": "1996", "title": "K.R. Lakshmanan v. State of Tamil Nadu", "text": "The Supreme Court sets the test that is still applied: whether skill predominates over chance."}, {"when": "2026", "title": "RIVR opens in Gurugram", "text": "A members' club for poker, played as a game of skill."}]}$$),
  (12, 'cards', $${"eyebrow": "Join the inner circle", "heading": "Earned at the table. Not bought.", "intro": "RIVR is members only. Every player signs up and is verified before they play, and your tier rises with the hours you play.", "cards": [{"label": "Every member", "title": "Member", "text": "Where everyone starts: the waitlist from the app, points for every hour, and RIVR Rewards on your rake."}, {"label": "After the Academy", "title": "Academy graduate", "text": "For members who finish RIVR Academy: ₹1,000 on your first buy-in after you graduate."}, {"label": "From the first night", "title": "Founders' Circle", "text": "For the members who open the club with us: first call on every waitlist."}, {"label": "By invitation", "title": "Black card", "text": "For the club's regulars at the higher stakes. The club sets out its terms before launch."}], "action": {"label": "Join RIVR", "to": "sign-up"}}$$),
  (13, 'feature', $${"eyebrow": "The RIVR app", "heading": "Done waiting for a seat?", "text": "See tonight's tables and their open seats, join the waitlist before you leave home, and get called to your seat.", "points": ["Live tables", "The waitlist", "Your seat, held"], "action": {"label": "Join the waitlist", "to": "waitlist"}, "image": "/media/app-home.webp", "alt": "The RIVR app's Home: tonight's tables with their open seats, the bad-beat jackpot and the next tournament"}$$),
  (14, 'cards', $${"eyebrow": "What's on", "heading": "Always something on the felt.", "intro": "Tournament nights and house promotions, for members who like a little more on the line.", "cards": [{"label": "Tournaments", "title": "Tournament nights", "text": "RIVR Sunday with ₹5,00,000 guaranteed, and the weekly games around it.", "points": ["RIVR Sunday", "The RIVR League"], "link": {"label": "Full calendar", "page": "tournaments"}}, {"label": "House promotions", "title": "On the house", "text": "Rewards dealt at every table, for members only.", "points": ["High hands", "The bad-beat jackpot", "Buy-in bonus Tuesday", "₹1,000 for each side of a referral"], "link": {"label": "See promotions", "page": "promotions"}}]}$$),
  (15, 'calendar', $${"heading": "Tournaments"}$$),
  (16, 'cards', $${"eyebrow": "The journal", "heading": "Sharpen your game.", "intro": "Strategy, rules and etiquette, written by people who play.", "cards": [{"label": "Learn", "title": "Texas Hold'em for beginners", "link": {"label": "Read", "page": "journal-holdem-basics"}}, {"label": "Learn", "title": "Pot-Limit Omaha: what changes", "link": {"label": "Read", "page": "journal-plo-basics"}}, {"label": "The room", "title": "Live poker etiquette", "link": {"label": "Read", "page": "journal-live-etiquette"}}, {"label": "Strategy", "title": "Bankroll basics", "link": {"label": "Read", "page": "journal-bankroll"}}]}$$),
  (17, 'faq', $${"heading": "Good questions.", "questions": [{"question": "What is RIVR?", "answer": "A members' poker club on the upper floor of Glaza, M3M 65th Avenue, Gurugram: six tables of no-limit hold'em from 50/100, a Private Room, tournaments every week, and a cage that pays out the same night. It opens on Sunday 15 November."}, {"question": "How do I become a member?", "answer": "Sign up in the RIVR app with your mobile number, then finish the identity check with DigiLocker and a selfie. You must be 18 or over. Check in at the door with the card in your app."}, {"question": "I'm new to live poker. Is RIVR for me?", "answer": "Yes. The dealers and the floor will walk you through how the room runs, 50/100 is a comfortable place to start, and RIVR Academy teaches the game in small batches with a coach."}, {"question": "How do I pay and cash out?", "answer": "At the cage, by UPI or in cash. You cash out at the cage the same night. TDS is deducted on winnings as the law requires, and the cage asks for your PAN."}, {"question": "When is RIVR open?", "answer": "From 14:00 to 08:00, from Sunday 15 November."}]}$$),
  (18, 'statement', $${"eyebrow": "Opens Sunday 15 November", "lines": ["Hold your nerve."], "text": "Upper floor, Glaza, M3M 65th Avenue, Gurugram.", "action": {"label": "Join RIVR", "to": "sign-up"}, "image": "/media/chips.webp", "note": "Concept visualisation"}$$),
  (19, 'map', $${"heading": "Find us", "address": "Upper floor, Glaza, M3M 65th Avenue, Gurugram", "hours": "Open 14:00 to 08:00.", "email": "info@rivrpoker.com", "directionsUrl": "https://www.google.com/maps/search/?api=1&query=Glaza%2C%20M3M%2065th%20Avenue%2C%20Gurugram"}$$)
) as b (position, kind, content);

-- About: the club, its standard and the law behind it, and how the room runs.
insert into public.site_block (venue_id, page_id, position, kind, content)
select '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000005d1', b.position, b.kind, b.content::jsonb
from (values
  (1, 'hero', $${"eyebrow": "About us", "heading": "About RIVR", "text": "A members' poker club in Gurugram, built for players who want more from their game."}$$),
  (2, 'story', $${"eyebrow": "A new standard", "heading": "Poker, run properly.", "paragraphs": ["RIVR was born from a love of the game and impatience with how it is usually run: home games that end in arguments, rooms where nobody counts the pot, and cash-outs that take days.", "So we built the opposite. Trained dealers who log every hand, a cage that pays out the same night, a floor that applies one set of rules to everyone, and members who are verified before they sit down."], "figures": [{"value": "6", "label": "Tables"}, {"value": "2", "label": "Rooms"}, {"value": "14:00", "label": "Doors open, until 08:00"}], "image": "/media/dealers.webp", "alt": "A dealer in a waistcoat deals at a table"}$$),
  (3, 'cards', $${"eyebrow": "At a glance", "heading": "RIVR in six lines.", "cards": [{"title": "Six tables", "text": "Five in the main room and the Private Room."}, {"title": "No-limit hold'em", "text": "Cash games from 50/100, and pot-limit Omaha as the room asks for it."}, {"title": "Tournaments every week", "text": "RIVR Sunday, with ₹5,00,000 guaranteed, and the RIVR League."}, {"title": "The cage", "text": "UPI or cash in, and paid out the same night."}, {"title": "The chef's menu", "text": "Complimentary, and served at your seat."}, {"title": "Verified members", "text": "18 and over, checked before they play."}]}$$),
  (4, 'timeline', $${"eyebrow": "Legal and compliance", "heading": "Poker is a game of skill.", "intro": "India's Supreme Court has long drawn the line between games of skill and games of chance. RIVR runs every table as a game of skill.", "items": [{"when": "1968", "title": "State of Andhra Pradesh v. K. Satyanarayana", "text": "The Supreme Court holds that rummy, played for stakes, is a game of skill."}, {"when": "1996", "title": "K.R. Lakshmanan v. State of Tamil Nadu", "text": "The Supreme Court sets the test that is still applied: whether skill predominates over chance."}]}$$),
  (5, 'cards', $${"eyebrow": "Tax and compliance", "heading": "Clean money, every night.", "cards": [{"title": "TDS on winnings", "text": "Deducted at the cage as the Income Tax Act requires, with a certificate for your return."}, {"title": "Your PAN", "text": "The cage asks for it, as the law requires for the amounts it pays."}, {"title": "Your own money", "text": "No credit from other players and no third-party buy-ins."}, {"title": "A full record", "text": "Every buy-in, cash-out and hand is logged, so every night balances."}]}$$),
  (6, 'rules', $${"heading": "Club policies", "rules": ["Members only, 18 and over, with a finished identity check.", "Check in at the door with the card in your app.", "One player to a hand. No advice from the rail and no phones on the table while a hand is on.", "Collusion, chip dumping and soft play are banned, and end a membership.", "No photographs or video in the gaming area.", "Chips stay in the club. Cash out at the cage.", "The floor decides any dispute at a table. Their decision on a hand is final.", "Treat dealers, staff and other players with respect. The floor may ask anyone to leave."]}$$),
  (7, 'faq', $${"heading": "Questions", "questions": [{"question": "Where is RIVR?", "answer": "On the upper floor of Glaza, M3M 65th Avenue, Sector 65, Gurugram."}, {"question": "When is it open?", "answer": "From 14:00 to 08:00, from Sunday 15 November."}, {"question": "Who can join?", "answer": "Anyone 18 or over. Sign up in the app and finish the identity check with DigiLocker and a selfie."}, {"question": "Is there a dress code?", "answer": "Smart casual. The floor may ask anyone to change who is not."}]}$$)
) as b (position, kind, content);

-- Membership: why, the tiers, points for every hour, and how to join.
insert into public.site_block (venue_id, page_id, position, kind, content)
select '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000005d2', b.position, b.kind, b.content::jsonb
from (values
  (1, 'hero', $${"eyebrow": "Membership", "heading": "RIVR membership", "text": "RIVR is members only. Sign up in the app, finish your identity check, and take your seat.", "action": {"label": "Join RIVR", "to": "sign-up"}}$$),
  (2, 'cards', $${"heading": "What membership gives you", "cards": [{"label": "♠", "title": "The room", "text": "Six tables, the Private Room, and a floor that runs them properly."}, {"label": "♦", "title": "The waitlist from home", "text": "Join from the app and get called to your seat."}, {"label": "♣", "title": "Food and drink", "text": "Brought to your seat while you play."}, {"label": "♥", "title": "Paid the same night", "text": "Cash out at the cage by UPI or in cash."}]}$$),
  (3, 'cards', $${"eyebrow": "Tiers", "heading": "Earned at the table.", "cards": [{"label": "Every member", "title": "Member", "points": ["Points for every hour you play", "RIVR Rewards: 5% of your rake back as points", "The waitlist from the app"]}, {"label": "After the Academy", "title": "Academy graduate", "points": ["Everything a member has", "₹1,000 on your first buy-in after you graduate"]}, {"label": "From the first night", "title": "Founders' Circle", "points": ["Everything a member has", "First call on every waitlist"]}, {"label": "By invitation", "title": "Black card", "points": ["For the club's regulars at the higher stakes", "Its terms are set out before launch"]}]}$$),
  (4, 'table', $${"heading": "Points for every hour", "intro": "Every hour you play earns points, more at the higher stakes. Points never turn into cash: they are for rewards.", "columns": ["Stake", "Points an hour"], "rows": [["NLH 50/100", "5"], ["NLH 100/200", "10"], ["Private Room", "20"]], "note": "Example rates: the club confirms its rates before launch. Only time seated at a table counts, not time away from it."}$$),
  (5, 'cards', $${"eyebrow": "How to join", "heading": "Three steps to your seat.", "cards": [{"label": "01", "title": "Sign up in the app", "text": "With your mobile number. It takes a minute."}, {"label": "02", "title": "Verify your identity", "text": "With DigiLocker and a selfie. You must be 18 or over."}, {"label": "03", "title": "Take your seat", "text": "Check in at the door with the card in your app, and the floor seats you."}], "action": {"label": "Join RIVR", "to": "sign-up"}}$$),
  (6, 'faq', $${"heading": "Membership questions", "questions": [{"question": "Does membership cost anything?", "answer": "Signing up is free. You pay only for what you play, at the cage."}, {"question": "What do I need to join?", "answer": "A phone with the RIVR app, and DigiLocker for the identity check. You must be 18 or over."}, {"question": "Can I come without a membership?", "answer": "No. RIVR is members only, so every player at the table is verified. You can sign up on your way in."}]}$$)
) as b (position, kind, content);

-- Promotions: the live ones from the floor, and the way they are run.
insert into public.site_block (venue_id, page_id, position, kind, content)
select '00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000005d3', b.position, b.kind, b.content::jsonb
from (values
  (1, 'hero', $${"eyebrow": "On the house", "heading": "Promotions", "text": "What RIVR runs for its members, live from the floor.", "action": {"label": "Join RIVR", "to": "sign-up"}}$$),
  (2, 'promotions', $${"heading": "Running now"}$$),
  (3, 'cards', $${"eyebrow": "How they work", "heading": "Fair, and the same for everyone.", "cards": [{"title": "Members only", "text": "Every promotion is for verified members, and shows in the app as it runs."}, {"title": "Paid as bonus or points", "text": "A bonus is credited to your balance and kept for its play; points are for rewards and never turn into cash."}, {"title": "The floor's word is final", "text": "On who qualified and when, as with every rule at RIVR."}]}$$)
) as b (position, kind, content);

