-- The journal and its articles.
insert into public.site_block (venue_id, page_id, position, kind, content)
select '00000000-0000-4000-8000-000000000001', b.page_id::uuid, b.position, b.kind, b.content::jsonb
from (values
  ('00000000-0000-4000-8000-0000000005d5', 1, 'hero', $${"eyebrow": "The journal", "heading": "Sharpen your game.", "text": "Strategy, rules and etiquette, written by people who play."}$$),
  ('00000000-0000-4000-8000-0000000005d5', 2, 'cards', $${"cards": [{"label": "Learn", "title": "Texas Hold'em for beginners", "text": "The rules of no-limit hold'em, from the blinds to the showdown.", "link": {"label": "Read", "page": "journal-holdem-basics"}}, {"label": "Learn", "title": "Pot-Limit Omaha: what changes", "text": "Four cards, two of them used, and a bet no bigger than the pot.", "link": {"label": "Read", "page": "journal-plo-basics"}}, {"label": "The room", "title": "Live poker etiquette", "text": "How a live table runs, and how to be the player others want beside them.", "link": {"label": "Read", "page": "journal-live-etiquette"}}, {"label": "Strategy", "title": "Bankroll basics", "text": "Playing within your means, so a bad night stays a bad night.", "link": {"label": "Read", "page": "journal-bankroll"}}]}$$),
  ('00000000-0000-4000-8000-0000000005d6', 1, 'hero', $${"eyebrow": "Learn", "heading": "Texas Hold'em for beginners", "text": "The rules of no-limit hold'em, from the blinds to the showdown."}$$),
  ('00000000-0000-4000-8000-0000000005d6', 2, 'text', $${"body": "Each player gets two cards face down. Five cards are dealt face up in the middle over three rounds: three at once (the flop), then one (the turn), then one more (the river). Your hand is the best five cards from your two and the five on the table.\n\nBefore any card is dealt, the two players left of the button put in the blinds: the small blind and the big blind. At 50/100 that is ₹50 and ₹100. Then each player in turn folds, calls the bet, or raises. In no-limit, a raise can be any amount up to everything in front of you.\n\nThere is a round of betting before the flop, after the flop, after the turn and after the river. If more than one player is left at the end, the hands are shown and the best one wins the pot.\n\nThe hands, best first: royal flush, straight flush, four of a kind, full house, flush, straight, three of a kind, two pair, one pair, high card.\n\nWhere to start: play fewer hands than you think, and play them with a raise. Position matters: acting last tells you what everyone else did first. And at a live table, take your time. The dealer will wait."}$$),
  ('00000000-0000-4000-8000-0000000005d7', 1, 'hero', $${"eyebrow": "Learn", "heading": "Pot-Limit Omaha: what changes", "text": "Four cards, two of them used, and a bet no bigger than the pot."}$$),
  ('00000000-0000-4000-8000-0000000005d7', 2, 'text', $${"body": "Omaha is dealt like hold'em, with a flop, a turn and a river, but each player gets four cards instead of two. The catch: your hand must use exactly two of your four cards and exactly three from the table. Four hearts in your hand and one on the table is not a flush.\n\nIn pot-limit, the largest bet you can make is the size of the pot, counting the call you would make first. The dealer will tell you the figure if you ask for the pot.\n\nWhat changes in play: with four cards each, hands run closer together, and big hands are common. A set or two pair that wins often in hold'em is often behind in Omaha. Draws are stronger too, because there are more ways to complete them.\n\nStart with hands whose four cards work together: pairs that can make sets, suited cards that can make the best flush, and connected cards that can make straights. Four cards that do not help one another rarely win a big pot."}$$),
  ('00000000-0000-4000-8000-0000000005d8', 1, 'hero', $${"eyebrow": "The room", "heading": "Live poker etiquette", "text": "How a live table runs, and how to be the player others want beside them."}$$),
  ('00000000-0000-4000-8000-0000000005d8', 2, 'text', $${"body": "Act in turn. Wait until the action reaches you before you fold, call or raise, even when you know what you will do. Acting early gives away information and can change the hand for others.\n\nSay what you are doing. A clear \"call\" or \"raise to five hundred\" is binding and avoids disputes. Put your chips in one motion: a bet made in several trips can be read as a string bet, which the floor will not allow.\n\nKeep your cards on the table and in view. Protect them with a chip, and never show them to a player still in the hand.\n\nOne player to a hand. Nobody advises a player during a hand, from the table or the rail. Phones stay off the table while a hand is on.\n\nIf something goes wrong, call the floor. The floor decides any dispute, and their decision on a hand is final. Tip the dealer if you like: it is not expected, and it is always appreciated."}$$),
  ('00000000-0000-4000-8000-0000000005d9', 1, 'hero', $${"eyebrow": "Strategy", "heading": "Bankroll basics", "text": "Playing within your means, so a bad night stays a bad night."}$$),
  ('00000000-0000-4000-8000-0000000005d9', 2, 'text', $${"body": "Your bankroll is the money you set aside for poker, and only for poker. It is not rent, savings or anything you would miss. Decide it before you play, and keep it apart from everything else.\n\nPlay a stake your bankroll can carry. Even the best players lose for nights or weeks at a time. A common guide for cash games is to hold twenty buy-ins or more for the stake you play: at 50/100, with a ₹5,000 buy-in, that is ₹1,00,000.\n\nMove down when you lose, not up. Chasing losses at a higher stake turns a bad night into a bad month.\n\nSet a stop for the night, win or lose, and keep to it. RIVR can hold a limit or a break for you if you ask: speak to the front desk, and the door, the waitlist and the cage will keep it until it ends.\n\nPoker is a game of skill, and you can still lose money at it. Play with money you can afford to lose."}$$),
  ('00000000-0000-4000-8000-0000000005da', 1, 'hero', $${"heading": "Terms of use", "text": "The terms of RIVR's website and app."}$$),
  ('00000000-0000-4000-8000-0000000005da', 2, 'text', $${"body": "RIVR publishes its full terms of use here before the club opens on Sunday 15 November. Until then, the house rules apply at the club, and the privacy notice says what personal data RIVR keeps.\n\nQuestions about these terms: info@rivrpoker.com."}$$)
) as b (page_id, position, kind, content);
